// Písmo pro faktury v PDF.
//
// PROČ JE PÍSMO V KÓDU A NE V SOUBORU
// PDF neumí české háčky a čárky z vestavěných písem — ř, ě, ů, č, š, ž tam
// prostě nejsou. Písmo se proto musí do dokumentu vložit. Kdyby leželo vedle
// jako soubor, záviselo by vykreslení faktury na tom, jestli se ten soubor
// dostal do nasazení; takhle je vždycky u toho.
//
// PROČ JE OŘÍZNUTÉ ŠIROCE, A NE ÚSPORNĚ
// Je to Source Sans 3 (stejné písmo jako na webu) oříznuté na základní
// latinku, Latin-1 a Latin Extended-A — 379 glyfů z několika tisíc, 32 kB
// na řez místo 646 kB. Pokrývá to češtinu, slovenštinu, polštinu, němčinu
// i maďarštinu.
//
// Užší výběr už jednou udělal škodu: v první verzi chybělo „ü" a na zkušební
// faktuře stálo „Fgnerovo náměstí" místo „Fügnerovo". Chybějící znak se totiž
// tiše přeskočí — na účetním dokladu je z toho špatná adresa a nikdo si toho
// nemusí všimnout. Adresy a jména odběratelů nikdo dopředu nekontroluje,
// takže se sem šetřit nevyplácí.
//
// Licence: SIL Open Font License 1.1 (Adobe, Source Sans 3).

function zBase64(casti: string[]): Uint8Array {
  const b64 = casti.join('');
  const binarne = atob(b64);
  const ven = new Uint8Array(binarne.length);
  for (let i = 0; i < binarne.length; i++) ven[i] = binarne.charCodeAt(i);
  return ven;
}

